1	// Monthly report page: total per category.
2	function totalsByCategory(items) {
3	  const out = {};
4	  for (const item of items) {
5	    out[item.category] = (out[item.category] || 0) + item.amount;
6	  }
7	  return out;
8	}
9	module.exports = { totalsByCategory };
